	private static void assertCloseWaitsForAdmittedWorker(
			Function<CloseableIteration<BindingSet>, CloseableIteration<BindingSet>> iteratorFactory,
			boolean seedReadAheadWorker) throws Exception {
		CountDownLatch callbackEntered = new CountDownLatch(1);
		CountDownLatch releaseCallback = new CountDownLatch(1);
		BlockingCheckpointIteration source = new BlockingCheckpointIteration();
		CloseableIteration<BindingSet> iteration = iteratorFactory.apply(source);
		ExecutorService queryExecutor = Executors.newSingleThreadExecutor();
		ExecutorService closeExecutor = Executors.newSingleThreadExecutor();
		try {
			if (seedReadAheadWorker) {
				assertTrue(iteration.hasNext());
				iteration.next();
			}

			try (QueryExecutionContext.Activation ignored = QueryExecutionContext.activateReplaySafepoint(() -> {
				source.callbackActive.set(true);
				callbackEntered.countDown();
				awaitUninterruptibly(releaseCallback);
				throw new IllegalStateException("replay requested");
			})) {
				QueryExecutionContext.ReplayContext replayContext = QueryExecutionContext.captureReplayContext();
				assertNotNull(replayContext);
				Future<?> query = queryExecutor.submit(() -> replayContext.get(() -> {
					while (iteration.hasNext()) {
						iteration.next();
					}
					return null;
				}));
				assertTrue(callbackEntered.await(5, TimeUnit.SECONDS),
						"an owned worker should enter its admitted replay checkpoint");

				CountDownLatch closeStarted = new CountDownLatch(1);
				Future<Boolean> close = closeExecutor.submit(() -> {
					closeStarted.countDown();
					Thread.currentThread().interrupt();
					iteration.close();
					return Thread.currentThread().isInterrupted();
				});
				assertTrue(closeStarted.await(5, TimeUnit.SECONDS));
				awaitTaskCompletion(query);
				assertThrows(TimeoutException.class, () -> close.get(250, TimeUnit.MILLISECONDS),
						"close must wait for the already-admitted worker to leave its callback");
				assertFalse(source.closedDuringCheckpoint.get(),
						"the delegate must remain open while its admitted callback is running");

				releaseCallback.countDown();
				assertTrue(close.get(5, TimeUnit.SECONDS),
						"waiting for the worker must restore the closer's interrupt status");
				assertTrue(source.callbackReturned.await(5, TimeUnit.SECONDS),
						"the callback should be able to unwind after close cancels the caller's wait");
				assertFalse(source.closedDuringCheckpoint.get(),
						"the delegate must only close after its admitted callback returns");
				assertTrue(source.closed.get(), "close must eventually close the delegate");
			}
		} finally {
			releaseCallback.countDown();
			if (callbackEntered.getCount() == 0) {
				source.callbackReturned.await(5, TimeUnit.SECONDS);
			}
			iteration.close();
			queryExecutor.shutdownNow();
			closeExecutor.shutdownNow();
			queryExecutor.awaitTermination(5, TimeUnit.SECONDS);
			closeExecutor.awaitTermination(5, TimeUnit.SECONDS);
		}
	}

	private static void awaitTaskCompletion(Future<?> task) throws Exception {
		try {
			task.get(5, TimeUnit.SECONDS);
		} catch (ExecutionException | CancellationException expected) {
			// Cancellation may surface as a task failure for iterators that block in Future.get().
		}
	}

	private static void awaitUninterruptibly(CountDownLatch latch) {
		boolean interrupted = false;
		while (true) {
			try {
				latch.await();
				break;
			} catch (InterruptedException e) {
				interrupted = true;
			}
		}
		if (interrupted) {
			Thread.currentThread().interrupt();
		}
	}

	private static void assertReplayFailure(Runnable operation) {
		RuntimeException failure = assertThrows(RuntimeException.class, () -> {
			try (QueryExecutionContext.Activation ignored = QueryExecutionContext.activateReplaySafepoint(
					() -> {
						throw new IllegalStateException("replay requested");
					})) {
				operation.run();
			}
		});
		assertTrue(QueryExecutionContext.isReplaySafepointFailure(failure),
				"worker failure must retain the replay signal");
	}

	private static void warmCommonPoolWorkers() throws Exception {
		ForkJoinPool commonPool = ForkJoinPool.commonPool();
		int parallelism = commonPool.getParallelism();
		CountDownLatch started = new CountDownLatch(parallelism);
		CountDownLatch release = new CountDownLatch(1);
		List<ForkJoinTask<?>> workers = new ArrayList<>(parallelism);
		for (int i = 0; i < parallelism; i++) {
			workers.add(commonPool.submit(() -> {
				started.countDown();
				try {
					release.await();
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
				}
			}));
		}
		try {
			assertTrue(started.await(10, TimeUnit.SECONDS),
					"common-pool workers should be established before the scope");
		} finally {
			release.countDown();
		}
		for (ForkJoinTask<?> worker : workers) {
			worker.join();
		}
	}

	private static final class CheckpointIteration extends AbstractCloseableIteration<BindingSet> {
		private final BindingSet bindingSet = new MapBindingSet();
		private int remaining = 32;

		@Override
		public boolean hasNext() {
			QueryExecutionContext.checkpointReplaySafepoint();
			return remaining > 0;
		}

		@Override
		public BindingSet next() {
			remaining--;
			return bindingSet;
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		protected void handleClose() {
		}
	}

	private static final class BlockingCheckpointIteration extends AbstractCloseableIteration<BindingSet> {
		private final BindingSet bindingSet = new MapBindingSet();
		private final AtomicBoolean closed = new AtomicBoolean();
		private final AtomicBoolean closedDuringCheckpoint = new AtomicBoolean();
		private final AtomicBoolean callbackActive = new AtomicBoolean();
		private final CountDownLatch callbackReturned = new CountDownLatch(1);

		@Override
		public boolean hasNext() {
			try {
				QueryExecutionContext.checkpointReplaySafepoint();
				return true;
			} finally {
				if (callbackActive.compareAndSet(true, false)) {
					callbackReturned.countDown();
				}
			}
		}

		@Override
		public BindingSet next() {
			return bindingSet;
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		protected void handleClose() {
			if (callbackActive.get()) {
				closedDuringCheckpoint.set(true);
			}
			closed.set(true);
		}
	}
